const r = $json;
const totalCleaned = Number(r.deleted_orphaned_embeddings || 0) +
                     Number(r.deleted_stale_chunks || 0) +
                     Number(r.deleted_stale_versions || 0) +
                     Number(r.deleted_empty_messages || 0) +
                     Number(r.deleted_empty_conversations || 0) +
                     Number(r.deleted_empty_leads || 0);

return {
  json: {
    "Trạng thái": "✅ ĐÃ DỌN DẸP SẠCH SẼ TOÀN BỘ DATABASE",
    "Tổng số bản ghi rác đã xóa": totalCleaned,
    "Vector Embedding mồ côi đã xóa": Number(r.deleted_orphaned_embeddings || 0),
    "Chunk văn bản lỗi đã xóa": Number(r.deleted_stale_chunks || 0),
    "Phiên bản tài liệu dở dang đã xóa": Number(r.deleted_stale_versions || 0),
    "Tin nhắn rỗng đã xóa": Number(r.deleted_empty_messages || 0),
    "Hội thoại mồ côi đã xóa": Number(r.deleted_empty_conversations || 0),
    "Lead rác không thông tin đã xóa": Number(r.deleted_empty_leads || 0),
    "Thời gian thực hiện": new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })
  }
};
